/* Interface des systèmes de jeu 2.0. */
const goalLabels={liberte:'Liberté',famille:'Liens & famille',creation:'Création',impact:'Contribution',securite:'Sécurité'};
const phaseLabels={expansion:'Expansion',recession:'Récession',recovery:'Reprise',slowdown:'Ralentissement'};
const strategyLabels={safe:'Prudente',balanced:'Équilibrée',bold:'Ambitieuse'};
const baseWelcome=welcomeBase,baseSources=sourcesBase;
function micro(label,value){return`<div class="data-row"><span>${label}</span><b>${value}</b></div>`}
function percent(x){return Math.round(x*100)+' %'}
function lock(reason){return reason?`<div class="locked">${esc(reason)}</div>`:''}
function skillBars(p){return Object.entries(Life.skills).map(([k,t])=>`<div class="skill-row"><span>${t}</span><div class="bar"><i style="width:${Math.round(p.skills[k])}%"></i></div><b>${Math.round(p.skills[k])}</b></div>`).join('')}
function miniProject(x){const t=Life.templates[x.type];return`<div class="mini-project"><div><b>${esc(x.name)}</b><small>${x.paused?'En pause':x.effort+' créneau'+(x.effort>1?'x':'')+' / an'} · ${Math.round(x.progress/x.target*100)} %</small></div><div class="bar"><i style="width:${Math.min(100,x.progress/x.target*100)}%"></i></div></div>`}
function lifeView(){const s=state,p=s.person,c=Life.country(s),f=Life.finance(s),n=Life.needs(s);return`${heading('Une vie ne se joue pas sur un seul choix.','Vos engagements se croisent. Leurs conséquences aussi.',`<button class="pill" onclick="guide()">? &nbsp; Prendre en main</button>`)}${profile()}<div class="stats">${stat('Santé',Math.round(p.health)+' <em>/ 100</em>',p.health)}${stat('Épanouissement',Math.round(p.happiness)+' <em>/ 100</em>',p.happiness)}${stat('Énergie',Math.round(p.energy)+' <em>/ 100</em>',p.energy)}${stat('Patrimoine net',money(p.alive?Life.balance(p):p.finalWorth||0))}</div>${p.statuses.length?`<div class="status-strip">${p.statuses.map(x=>`<span class="tag warning">${esc(x.label)} · ${x.years} an${x.years>1?'s':''}</span>`).join('')}</div>`:''}<div class="layout"><div><div class="section-head"><h3>${p.alive?'Votre prochain chapitre':'Ce qui reste de cette vie'}</h3><span class="eyebrow">${state.year} · ${p.age} ans</span></div>${!p.alive?ending():s.pending?eventView():`<div class="card event"><div class="eyebrow">Vos initiatives comptent aussi</div><h2>Qu’allez-vous faire de cette année ?</h2><p>Il vous reste ${Life.available(p)} créneaux. Vous pouvez apprendre, entretenir un lien, préparer une candidature ou démarrer un projet. Le temps réservé aux projets sera utilisé lorsque vous avancerez.</p><div class="row"><button class="btn" onclick="nav('actions')">Explorer mes possibilités</button><button class="btn primary" onclick="advance()">Clore cette année →</button></div></div>`}${p.projects.length?`<div class="section-head" style="margin-top:25px"><h3>Ce que vous construisez</h3><button class="muted" onclick="nav('projects')">Gérer mes projets ↗</button></div><div class="card">${p.projects.map(miniProject).join('')}</div>`:''}<div class="section-head" style="margin-top:26px"><h3>Les dernières traces</h3><button class="muted" onclick="nav('journal')">Le récit complet ↗</button></div>${timeline(s.journal.filter(x=>x.person===p.id).slice(-5).reverse())}</div><aside class="right"><div class="card"><h3>Le temps est votre première ressource</h3><div class="time-blocks">${Array.from({length:Life.capacity(p)},(_,i)=>`<span class="${i<p.timeSpent?'spent':i<p.timeSpent+Life.projectEffort(p)?'reserved':'free'}"></span>`).join('')}</div>${micro('Disponible',Life.available(p)+' créneaux')}${micro('Déjà utilisé',p.timeSpent+' créneaux')}${micro('Réservé aux projets',Life.projectEffort(p)+' créneaux')}${micro('Charge de travail',p.workload===3?'Intensive':p.workload===2?'Temps plein':p.workload===1?'Temps partiel':'Sans emploi salarié')}<p class="hint">8 créneaux de base, moins le travail, l’entreprise, les très jeunes enfants et les limites de santé.</p><label>Votre priorité de vie cette année</label><select aria-label="Priorité annuelle" onchange="act('focus',this.value)">${[['balance','Équilibre'],['career','Carrière : progression et pression'],['family','Présence : liens et réseau'],['health','Santé : récupération et stress']].map(([v,t])=>`<option value="${v}" ${p.focus===v?'selected':''}>${t}</option>`).join('')}</select><button class="btn primary next" onclick="advance()" ${!p.alive||s.pending?'disabled':''}>Vivre la prochaine année →</button>${s.pending?'<div class="hint">Répondez au chapitre en cours avant d’avancer.</div>':''}</div><div class="card"><h3>Votre boussole : ${goalLabels[p.goal]}</h3>${[['security','Sécurité'],['freedom','Liberté'],['connection','Liens'],['meaning','Sens & création']].map(([k,t])=>`<div class="need"><span>${t}</span><div class="bar"><i style="width:${n[k]}%"></i></div><small>${Math.round(n[k])}</small></div>`).join('')}<p class="hint">Votre épanouissement évolue aussi selon ce qui compte pour vous, pas uniquement selon votre fortune.</p></div><div class="card"><h3>Le monde & votre foyer</h3>${micro('Conjoncture',phaseLabels[s.world.phase])}${micro('Secteur porteur',Life.sectors[s.world.trend].name)}${micro('Marché annuel',`<span class="${s.market<0?'negative':'positive'}">${s.market>=0?'+':''}${percent(s.market)}</span>`)}${micro('Inflation annuelle',percent(s.world.inflation))}${micro('Solde annuel estimé',`<span class="${f.net<0?'negative':'positive'}">${money(f.net)}</span>`)}<button class="btn" onclick="nav('money')">Comprendre mon budget ↗</button></div></aside></div>`}
function eventView(){const e=state.pending;return`<article class="card event"><div class="eyebrow">${esc(e.category||'Une décision')} &nbsp; · &nbsp; ${state.year}</div><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="choices">${e.choices.map((x,i)=>{const reason=Life.canChoose(state,x);return`<button class="choice ${reason?'unavailable':''}" ${reason?'disabled':''} onclick="decide(${i})"><span><strong>${esc(x.label)}</strong><small>${esc(x.note)}</small>${reason?`<small class="negative">${esc(reason)}</small>`:''}</span><span class="arrow">↗</span></button>`}).join('')}</div><div class="hint">Les chances affichées sont celles du modèle de jeu, avec les informations actuelles.</div></article>`}
function decide(i){if(Life.choose(state,i)){save();render()}else toast(state.lastError||'Ce choix n’est plus accessible.')}
function advance(){if(!state.person.alive)return;const unused=Life.available(state.person);if(state.pending){toast('Répondez d’abord à la décision en cours.');return}if(Life.year(state)){save();render();window.scrollTo({top:0,behavior:'smooth'});if(state.person.age>=18&&state.person.alive)annualRecap(unused)}else toast('Impossible d’avancer pour le moment.')}
function annualRecap(unused){const s=state,a=s.annual,p=s.person,f=a.ledger;modal(`<div class="eyebrow">Une année de plus · ${s.year}</div><h2 style="margin-top:12px">${p.age} ans. Vos choix prennent forme.</h2><div class="recap-grid"><div><small>Patrimoine net</small><b class="${a.wealthDelta<0?'negative':'positive'}">${a.wealthDelta>=0?'+':''}${money(a.wealthDelta)}</b></div><div><small>Santé</small><b class="${a.healthDelta<0?'negative':'positive'}">${a.healthDelta>=0?'+':''}${a.healthDelta.toFixed(1)}</b></div><div><small>Épanouissement</small><b class="${a.happinessDelta<0?'negative':'positive'}">${a.happinessDelta>=0?'+':''}${a.happinessDelta.toFixed(1)}</b></div></div>${micro('Conjoncture',phaseLabels[s.world.phase])}${micro('Solde du foyer après charges',money(f?.net||0))}<p>${unused>0?`${unused} créneau${unused>1?'x n’ont':' n’a'} pas été utilisé${unused>1?'s':''}. Laisser du temps libre est aussi une manière de vivre.`:'Votre temps était entièrement engagé. Gardez un œil sur votre énergie et votre stress.'}</p>${p.projects.length?`<div class="recap-projects">${p.projects.map(miniProject).join('')}</div>`:''}<button class="btn primary" style="width:100%;margin-top:20px" onclick="document.getElementById('modal').close()">Découvrir mon prochain chapitre →</button>`)}
function actionsView(){const p=state.person;return`${heading('Des initiatives, pas seulement des réponses.','Vos créneaux libres servent à construire ce que le hasard ne vous propose pas.',`<span class="pill">${Life.available(p)} créneaux libres</span>`)}<div class="quick-strip"><button onclick="nav('projects')">◈ &nbsp; Projets sur plusieurs années →</button><button onclick="nav('career')">↗ &nbsp; Offres & progression de carrière →</button></div><div class="grid"><div class="card"><div class="eyebrow">Compétences · 1 créneau</div><h3>Apprendre avec une direction</h3><p>Cinq compétences distinctes ouvrent des parcours différents. La curiosité influence votre progression.</p>${skillBars(p)}<label for="learn-skill">Compétence à développer</label><select id="learn-skill">${Object.entries(Life.skills).map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select><button class="btn" onclick="act('learn',document.getElementById('learn-skill').value)" ${!p.alive||!p.points?'disabled':''}>Approfondir ↗</button></div><div class="card"><div class="eyebrow">Temps & récupération</div><h3>Tenir dans la durée</h3><p>Le repos baisse le stress et restaure l’énergie. Le sport soutient la santé ; une blessure impose de récupérer.</p>${micro('Stress',Math.round(p.stress)+' / 100')}${micro('Énergie',Math.round(p.energy)+' / 100')}<div class="row"><button class="btn" onclick="act('rest')" ${!p.alive||!p.points?'disabled':''}>Me reposer · 1</button><button class="btn" onclick="act('sport')" ${!p.alive||!p.points?'disabled':''}>Faire du sport · 1</button></div><button class="btn" onclick="launchProject('therapy')" ${p.age<16||!p.alive?'disabled':''}>Un accompagnement dans la durée</button></div><div class="card"><div class="eyebrow">Liens · 1 créneau</div><h3>Être présent</h3><p>Les liens se construisent dans le temps. Vous pouvez aussi interagir avec chaque proche, réparer une tension ou transmettre une compétence.</p><div class="row"><button class="btn" onclick="act('social')" ${!p.alive||!p.points?'disabled':''}>Voir mes proches</button><button class="btn" onclick="nav('people')">Choisir une personne ↗</button></div></div><div class="card"><div class="eyebrow">Rencontres · 1 créneau</div><h3>Laisser quelqu’un entrer</h3><p>Une rencontre n’est pas une promesse. Chance estimée de relation : ${percent(Life.chance(state,'date'))}. Votre aisance et votre réseau jouent un rôle.</p><button class="btn" onclick="act('date')" ${p.age<18||p.partner||!p.alive||!p.points?'disabled':''}>Faire une rencontre</button>${p.partner?'<p class="hint">Vous êtes déjà en couple.</p>':''}</div><div class="card"><div class="eyebrow">Revenu immédiat · 2 créneaux</div><h3>Une mission ponctuelle</h3><p>Une activité temporaire rapporte ${money(Life.reference(state)*.085)}. Elle peut financer un projet ou absorber une difficulté, au prix d’énergie et de temps.</p><button class="btn" onclick="act('gig')" ${p.age<18||!p.alive||p.points<2?'disabled':''}>Prendre une mission</button></div><div class="card"><div class="eyebrow">Contribution · 1 créneau</div><h3>Faire une différence</h3><p>Une contribution de ${money(Life.reference(state)*.05)} soutient une initiative locale. Un projet associatif permet d’aller plus loin.</p><div class="row"><button class="btn" onclick="act('donate')" ${p.age<18||!p.alive||!p.points?'disabled':''}>Contribuer</button><button class="btn" onclick="launchProject('community')">Créer un collectif ↗</button></div></div></div>`}
function careerView(){const p=state.person,sec=p.career?Life.sectors[p.career.sector]:null,items=Life.offers(state);return`${heading('Le travail prend une place. Choisissez laquelle.','Les offres restent identiques cette année. Chaque candidature consomme un créneau, sans garantie.',`<span class="pill">${Life.available(p)} créneaux disponibles</span>`)}<div class="grid"><div class="card"><div class="eyebrow">Votre situation</div><h3>${esc(p.job)}</h3><div class="big-number">${money(p.salary)} <small>/ an</small></div>${micro('Qualification',p.education>=2?'Diplôme supérieur':p.education===1?'Qualification métier':'Sans diplôme professionnel')}${micro('Expérience dans le poste',(p.career?.years||0)+' ans')}${micro('Niveau du parcours',p.career?(p.career.level+1)+' / 4':'—')}${micro('Pension annuelle acquise',money(p.pension))}${p.career?`<div class="row"><button class="btn primary" onclick="act('promotion')" ${!p.alive||p.points<1?'disabled':''}>Demander une promotion · ${percent(Life.chance(state,'promotion'))}</button><button class="btn" onclick="careerRhythm()">Temps de travail</button></div><button class="btn danger" onclick="confirmQuit()">Quitter ce poste</button>`:`<p>Votre prochain poste peut être un nouveau départ. Les emplois d’entrée de parcours sont accessibles sans diplôme spécifique.</p>`}${p.age>=60&&!p.retired?'<button class="btn" onclick="act(\'retire\')">Prendre ma retraite</button>':''}</div><div class="card"><h3>Ce que vous apportez</h3>${skillBars(p)}${micro('Réseau',Math.round(p.network)+' / 100')}${micro('Réputation',Math.round(p.reputation)+' / 100')}${micro('Préparation aux entretiens',p.preparation+' / 10')}<div class="row"><button class="btn" onclick="act('prepare')" ${p.points<1||!p.alive?'disabled':''}>Préparer · 1</button><button class="btn" onclick="act('network')" ${p.points<1||!p.alive?'disabled':''}>Développer mon réseau · 1</button></div><button class="btn" onclick="act('scholarship')" ${p.scholarship||p.age<16||p.age>40||!p.alive?'disabled':''}>${p.scholarship?'Bourse de formation active':'Déposer un dossier de bourse · 1'}</button></div></div><div class="section-head" style="margin-top:30px"><h3>Le marché du travail · ${state.year}</h3><span class="pill">${phaseLabels[state.world.phase]}</span></div><div class="jobs-grid">${items.map(o=>{const sec=Life.sectors[o.sector],blocked=p.education<o.degree?'Qualification professionnelle requise':p.actions[o.id]?'Candidature déjà envoyée cette année':p.age<18?'Accessible à 18 ans':!p.alive?'Cette vie est terminée':'';return`<div class="card job-card"><div class="eyebrow">${sec.name}</div><h3>${esc(o.title)}</h3><div class="big-number">${money(o.salary)}<small> / an</small></div>${micro('Rythme',o.load===1?'Temps partiel':o.load===3?'Intensif':'Temps plein')}${micro('Compétence clé',Life.skills[sec.skill])}${micro('Chance de recrutement',percent(Life.chance(state,'job',o)))}<p class="hint">Le diplôme, l’expérience, les compétences, le réseau et la conjoncture modifient cette estimation. Un refus ne fait pas perdre votre poste actuel.</p><button class="btn primary" ${blocked||p.points<1?'disabled':''} onclick="act('applyJob','${o.id}')">Candidater · 1 créneau</button>${lock(blocked)}</div>`}).join('')}</div><div class="notice">Vous voulez changer de voie ? Une qualification, un cursus ou une reconversion peuvent se préparer dans Projets. Vous pouvez garder un travail à temps partiel pendant votre formation.</div>`}
function projectsView(){const p=state.person;return`${heading('Les grandes choses prennent du temps.','Trois projets simultanés maximum. Chaque projet réserve du temps et finance ses frais à la fin de l’année.',`<span class="pill">${Life.projectEffort(p)} créneaux engagés</span>`)}${p.projects.length?`<div class="grid">${p.projects.map(x=>{const cost=Life.projectCost(state,x),years=Math.ceil((x.target-x.progress)/Math.max(.5,x.effort*(x.strategy==='bold'?1.35:x.strategy==='safe'?.85:1)));return`<div class="card project-card"><div class="section-head"><span class="eyebrow">${x.paused?'En pause':'En cours depuis '+x.started}</span><span class="tag">${strategyLabels[x.strategy]}</span></div><h3>${esc(x.name)}</h3><div class="progress-large"><div class="bar"><i style="width:${Math.min(100,x.progress/x.target*100)}%"></i></div><span>${Math.round(x.progress/x.target*100)} %</span></div>${micro('Rythme réservé',x.effort+' créneaux / an')}${micro('Frais cette année active',money(cost))}${micro('Déjà investi',money(x.spent))}${['degree','training','retrain'].includes(x.type)?micro('Financement',x.funding==='loan'?'Prêt autorisé si nécessaire':'Liquidités uniquement'):''}${micro('Préparation du projet',x.quality+' / 10')}${micro('Durée restante indicative',years+' an'+(years>1?'s':''))}${['startup','book','migration','adoption','marathon'].includes(x.type)?micro('Chance estimée à l’issue',percent(Life.chance(state,'project',x))):''}<div class="row"><button class="btn" onclick="projectRhythm(${x.id})">Ajuster le rythme</button><button class="btn" onclick="act('projectPause',{id:${x.id}})">${x.paused?'Reprendre':'Mettre en pause'}</button></div><button class="btn danger" onclick="abandonProject(${x.id})">Abandonner</button>${p.cash<cost&&!x.paused&&x.funding!=='loan'?'<div class="locked">Frais non couverts par vos liquidités actuelles : le projet n’avancera pas sans financement.</div>':''}</div>`}).join('')}</div>`:'<div class="card empty"><h3>Aucun projet engagé pour le moment.</h3><p>Vous pouvez vivre sans tout planifier. Si une envie grandit, donnez-lui du temps.</p></div>'}<div class="section-head" style="margin-top:30px"><h3>Quelque chose à construire</h3><span class="history-total">12 parcours, plusieurs manières de les mener</span></div><div class="grid">${Object.entries(Life.templates).filter(([id,t])=>p.age>=t.minAge&&(!t.maxAge||p.age<=t.maxAge)).map(([id,t])=>{const reason=Life.canStart(state,id);return`<div class="card"><div class="eyebrow">${t.work} unités de travail · ${t.minAge} ans et +</div><h3 style="margin-top:12px">${t.name}</h3><p>${t.description}</p>${micro('Frais annuels de base',money(Life.reference(state)*t.cost))}<button class="btn" onclick="launchProject('${id}')" ${reason?'disabled':''}>Construire ce projet ↗</button>${lock(reason)}</div>`}).join('')}</div>${p.finished.length?`<div class="card" style="margin-top:25px"><h3>Les projets qui ont fait votre histoire</h3>${p.finished.map(x=>`<div class="data-row"><span>${x.year} · ${esc(x.name)}</span><b class="${x.success?'positive':'negative'}">${x.success?'Accompli':'Tentative'}</b></div>`).join('')}</div>`:''}`}
function launchProject(type){const t=Life.templates[type],reason=Life.canStart(state,type);if(reason){toast(reason);return}modal(`<div class="eyebrow">Un engagement dans la durée</div><h2 style="margin-top:12px">${t.name}</h2><p>${t.description}</p><label for="project-effort">Temps réservé chaque année</label><select id="project-effort">${[1,2,3].filter(n=>n<=Life.available(state.person)).map(n=>`<option value="${n}" ${n===2?'selected':''}>${n} créneau${n>1?'x':''} · environ ${Math.ceil(t.work/n)} ans</option>`).join('')}</select>${['degree','training','retrain','startup'].includes(type)?`<label for="project-sector">Secteur visé</label><select id="project-sector">${Object.entries(Life.sectors).map(([id,t])=>`<option value="${id}">${t.name}</option>`).join('')}</select>`:''}${type==='migration'?`<label for="project-destination">Destination</label><select id="project-destination">${Life.countries.filter(x=>x.code!==state.person.country&&x.code!=='XX').map(x=>`<option value="${x.code}">${x.name}</option>`).join('')}</select>`:''}${['degree','training','retrain'].includes(type)?'<label for="project-funding">Financer les frais</label><select id="project-funding"><option value="loan">Liquidités, puis prêt de formation si nécessaire</option><option value="cash">Mes liquidités uniquement · pause si insuffisantes</option></select>':''}<label for="project-strategy">Votre approche</label><select id="project-strategy"><option value="safe">Prudente · frais ×0,8 · rythme ×0,85 · préparation renforcée</option><option value="balanced" selected>Équilibrée · frais habituels</option><option value="bold">Ambitieuse · frais ×1,3 · rythme ×1,35 · risque accru</option></select><div class="notice">${type==='startup'?`À l’issue, un capital supplémentaire de ${money(Life.reference(state)*.15)} à ${money(Life.reference(state)*.5)} sera nécessaire selon l’approche. Un lancement ambitieux vise davantage de revenus mais expose plus votre entreprise aux crises.`:'Les projets avancent quand vous clôturez une année. Les frais sont prélevés avant le bilan annuel. Les formations peuvent utiliser un prêt si vous l’autorisez. Les autres projets attendent si leur budget manque.'}</div><button class="btn primary" style="width:100%;margin-top:16px" onclick="confirmProject('${type}')">Réserver du temps et commencer →</button>`)}
function confirmProject(type){const opts={type,effort:Number($('#project-effort').value),strategy:$('#project-strategy').value,sector:$('#project-sector')?.value||'tech',destination:$('#project-destination')?.value||'FR',funding:$('#project-funding')?.value||'cash'};const result=Life.action(state,'startProject',opts);if(result.ok){save();$('#modal').close();page='projects';render()}toast(result.message)}
function projectRhythm(id){const x=state.person.projects.find(x=>x.id===id);modal(`<h2>Le rythme de ${esc(x.name)}</h2><p>Un rythme plus lent conserve vos progrès. Le budget se paie pour chaque année active. Un rythme ambitieux progresse plus vite mais coûte plus cher et augmente la pression.</p><label for="effort">Créneaux réservés</label><select id="effort">${[1,2,3].map(n=>`<option value="${n}" ${x.effort===n?'selected':''}>${n} créneau${n>1?'x':''}</option>`).join('')}</select><button class="btn primary" style="margin-top:20px" onclick="const n=Number(document.getElementById('effort').value);document.getElementById('modal').close();act('projectEffort',{id:${id},effort:n})">Ajuster</button>`)}
function abandonProject(id){modal(`<h2>Abandonner ce projet ?</h2><p>Le temps futur est libéré. Les dépenses déjà engagées ne sont pas remboursées. Une tentative interrompue ne retire pas vos compétences.</p><button class="btn danger" onclick="document.getElementById('modal').close();act('projectAbandon',{id:${id}})">Abandonner ce projet</button>`)}
function confirmQuit(){modal(`<h2>Quitter votre poste ?</h2><p>Votre salaire s’arrêtera. Vos réserves et votre foyer doivent pouvoir financer vos engagements.</p>${micro('Liquidités',money(state.person.cash))}${micro('Dépenses annuelles courantes',money(Life.costs(state)))}<button class="btn danger" onclick="document.getElementById('modal').close();act('quit')">Confirmer ma démission</button>`)}
function careerRhythm(){modal(`<h2>Quelle place pour le travail ?</h2><p>Le temps plein vaut 2 créneaux. Le temps partiel vaut 1 créneau et environ 65 % du salaire de référence du poste. L’intensif vaut 3 créneaux, 125 % du salaire et davantage de stress.</p><div class="choices">${[[1,'Temps partiel'],[2,'Temps plein'],[3,'Intensif']].map(([v,t])=>`<button class="choice" onclick="document.getElementById('modal').close();act('workload',${v})"><strong>${t}</strong><span>→</span></button>`).join('')}</div><p class="hint">Négocier ce changement consomme un créneau.</p>`)}
function moneyView(){const p=state.person,f=Life.finance(state),b=p.business;return`${heading('Le patrimoine compte. Le budget aussi.','Revenus du foyer, prélèvements, intérêts, trésorerie et marchés partagent la même simulation.')}<div class="stats">${stat('Patrimoine net',money(Life.balance(p)))}${stat('Liquidités',money(p.cash))}${stat('Revenus annuels du foyer',money(f.earnings))}${stat('Solde annuel estimé',money(f.net))}</div><div class="grid"><div class="card"><h3>Le budget expliqué</h3>${micro('Revenus du foyer',money(f.earnings))}${micro('Prélèvements progressifs',money(-f.tax))}${micro('Vie courante',money(-f.living))}${micro('Entretien immobilier',money(-f.maintenance))}${micro('Intérêts de dette',money(-f.interest))}${micro('Capital remboursé',money(-f.principal))}<div class="total-row">${micro('Reste estimé',money(f.net))}</div><p class="hint">Aide familiale jusqu’à 23 ans et soutien minimal hors emploi sont calculés dans le bilan annuel. Les frais des projets sont prélevés séparément avant ce bilan.</p><label>Niveau de vie</label><select aria-label="Niveau de vie" onchange="act('lifestyle',this.value)">${[['frugal','Sobre'],['normal','Équilibré'],['comfort','Confortable']].map(([v,t])=>`<option value="${v}" ${p.lifestyle===v?'selected':''}>${t}</option>`).join('')}</select><label>Part du surplus investie : <b>${p.saving} %</b></label><input aria-label="Épargne automatique" type="range" min="0" max="80" value="${p.saving}" onchange="act('saving',Number(this.value))"></div><div class="card"><h3>La sécurité se prépare</h3>${micro('Réserve en dépenses courantes',(p.cash/Math.max(1,f.living)*12).toFixed(1)+' mois')}${micro('Dette totale',money(p.debt))}${micro('Dont crédit immobilier',money(p.loan))}${micro('Taux annuel de base',percent(state.world.rate))}${micro('Couverture santé',p.insurance?'Activée':'Non activée')}<button class="btn" onclick="act('insurance',${!p.insurance})">${p.insurance?'Désactiver':'Activer'} la couverture</button><button class="btn" onclick="act('repay')">Rembourser avec mes liquidités</button><p class="hint">La couverture coûte 3,5 % du revenu local de référence par an. Elle réduit les frais de consultation et certains risques. Une restructuration peut intervenir si la dette devient insoutenable ; le crédit sera alors restreint.</p></div>${[['funds','Portefeuille diversifié','Suit le marché simulé. Les crises sont communes aux placements, au recrutement et aux entreprises.'],['speculation','Placements spéculatifs','Une exposition amplifiée au marché, avec des variations supplémentaires très fortes.']].map(([id,t,d])=>`<div class="card"><div class="eyebrow">Placement</div><h3 style="margin-top:12px">${t}</h3><div class="big-number">${money(p[id])}</div><p>${d}</p><div class="row"><button class="btn" onclick="investment('${id}','invest')" ${p.age<18||!p.alive?'disabled':''}>Investir</button><button class="btn" onclick="investment('${id}','withdraw')" ${p.age<18||!p.alive?'disabled':''}>Vendre</button></div></div>`).join('')}<div class="card"><h3>Votre logement</h3><div class="big-number">${money(p.home)}</div><p>${p.home?'Votre logement suit un marché immobilier corrélé à l’économie. Entretien : 1,2 % de la valeur par an.':'Apport de 22 % du prix, crédit limité par les revenus du foyer. Les remboursements ne peuvent pas dépasser la capacité simulée.'}</p><button class="btn" onclick="act('${p.home?'sellhome':'home'}')" ${!p.alive?'disabled':''}>${p.home?'Vendre le logement':'Étudier un achat'}</button></div><div class="card"><h3>Votre entreprise</h3>${b?`${micro('Chiffre d’affaires',money(b.revenue))}${micro('Charges fixes annuelles',money(b.fixed))}${micro('Trésorerie professionnelle',money(b.cash))}${micro('Revenu versé au foyer',money(b.profit))}${micro('Valeur estimée',money(b.value))}${micro('Salariés',b.employees)}${micro('Dépendance aux grands clients',Math.round(b.concentration)+' / 100')}<label>Stratégie</label><select aria-label="Stratégie de l’entreprise" onchange="act('businessStrategy',this.value)">${Object.entries(strategyLabels).map(([v,t])=>`<option value="${v}" ${b.strategy===v?'selected':''}>${t}</option>`).join('')}</select><div class="row"><button class="btn" onclick="businessFund()">Injecter des fonds</button><button class="btn" onclick="act('businessMarket')">Prospecter · 1</button><button class="btn" onclick="act('businessHire')">Recruter · 1</button><button class="btn" onclick="act('sellbusiness')">Céder · 1</button></div><p class="hint">Le personnel augmente le potentiel de chiffre d’affaires et les coûts fixes. Une entreprise sans trésorerie peut fermer. Sa dette reste séparée de la dette personnelle.</p>`:`<p>Une activité se construit avant de générer un revenu : test du marché, préparation et capital de lancement.</p><button class="btn" onclick="launchProject('startup')">Construire une activité ↗</button>`}</div></div><div class="card" style="margin-top:22px"><h3>Les risques que vous avez pris</h3>${p.riskLog.slice(-7).reverse().map(x=>`<div class="risk-row"><span>${x.year} · ${esc(x.title)}</span><small>${percent(x.prob)} estimés</small><b class="${x.result?'positive':'negative'}">${x.result?'Issue favorable':'Issue défavorable'}</b></div>`).join('')||'<p>Les tentatives de carrière, projets et placements seront consignés ici.</p>'}<p class="hint">Un résultat favorable ne prouve pas qu’un pari était raisonnable. L’estimation et la somme exposée sont enregistrées avant le résultat.</p></div><div class="notice">Les règles fiscales, monétaires, financières et sociales sont des abstractions de jeu. Les UPA sont une monnaie fictive de pouvoir d’achat. Les profils nationaux restent approximatifs.</div>`}
function businessFund(){modal(`<h2>Renforcer la trésorerie</h2><p>Le transfert quitte vos liquidités personnelles et rejoint l’entreprise. Ce capital peut être perdu si elle ferme.</p><label for="bizamount">Montant en UPA</label><input id="bizamount" type="number" min="1" max="${Math.floor(state.person.cash)}" value="${Math.floor(state.person.cash*.1)}"><button class="btn primary" style="margin-top:15px" onclick="const n=Number(document.getElementById('bizamount').value);document.getElementById('modal').close();act('businessCash',n)">Injecter · 1 créneau</button>`)}
function relationCard(x,type){const actual=state.people[x.id],isChild=type==='Enfant';return`<div class="card relation-card"><div class="eyebrow">${type} · ${x.alive===false?'Décédé·e':(actual?.age??x.age)+' ans'}</div>${personRow(x.name,`${actual?.job||'Une vie à soi'} · lien ${Math.round(x.bond)}/100`,'',actual||x)}${actual?`<div class="hint">Aspiration : ${esc(actual.ambition||goalLabels[actual.goal])}${actual.partner?' · en couple avec '+esc(actual.partner.name):''}${actual.children.length?' · '+actual.children.length+' enfant(s)':''}</div>`:''}${x.compatibility?micro('Compatibilité',x.compatibility+' / 100'):''}${type==='Partenaire'?micro('Projet parental',x.wantsChildren?'Souhaite des enfants':'Ne souhaite pas d’enfant actuellement'):''}${x.alive!==false?`<div class="row"><button class="btn" onclick="interact(${x.id},'listen')">Écouter · 1</button><button class="btn" onclick="interact(${x.id},'repair')">Réparer · 1</button>${isChild?`<button class="btn" onclick="interact(${x.id},'mentor')">Transmettre · 1</button><button class="btn" onclick="interact(${x.id},'gift')">Soutenir · 1</button>`:''}</div>`:''}${x.memories?.length?`<div class="memory"><small>Ce qui reste entre vous</small>${x.memories.slice(-2).map(m=>`<p>${m.year} · ${esc(m.text)}</p>`).join('')}</div>`:''}</div>`}
function interact(id,mode){act('person',{id,mode})}
function peopleView(){const p=state.person;return`${heading('Personne n’est un simple figurant.','Vos proches ont leurs besoins. Vos enfants grandissent, travaillent, rencontrent et fondent parfois leur propre famille.')}<div class="section-head"><h3>Votre couple</h3></div>${p.partner?relationCard(p.partner,'Partenaire'):`<div class="card"><p>Vous pouvez chercher une relation ou construire votre vie autrement.</p><button class="btn" onclick="act('date')" ${p.age<18||!p.alive?'disabled':''}>Faire une rencontre · ${percent(Life.chance(state,'date'))}</button></div>`}${p.partner?'<button class="btn danger" style="margin-bottom:23px" onclick="confirmSeparate()">Me séparer</button>':''}<div class="section-head"><h3>Vos enfants</h3><div class="row"><button class="btn" onclick="act('child')" ${!p.alive?'disabled':''}>Projet parental · 1</button><button class="btn" onclick="launchProject('adoption')" ${!p.alive?'disabled':''}>Parcours d’adoption</button></div></div>${p.children.length?`<div class="card"><label>Votre manière de les accompagner</label><select aria-label="Accompagnement des enfants" onchange="act('familyPolicy',this.value)">${[['balanced','Équilibre'],['present','Présence & confiance'],['education','Investir dans l’éducation · 4 % du revenu de référence / enfant mineur / an'],['autonomy','Autonomie & relations']].map(([v,t])=>`<option value="${v}" ${p.familyPolicy===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="grid">${p.children.map(x=>relationCard(x,'Enfant')).join('')}</div>`:'<div class="card"><p>Vous n’avez pas d’enfant. Un projet parental demande l’accord de votre partenaire ; l’adoption est un parcours distinct, ouvert aussi hors couple.</p></div>'}<div class="section-head" style="margin-top:28px"><h3>Votre cercle</h3></div><div class="grid">${p.friends.slice(-10).map(x=>relationCard(x,'Amitié')).join('')||'<div class="card"><p>Les rencontres de votre vie dessineront votre cercle.</p></div>'}</div><div class="card" style="margin-top:22px"><h3>Vos racines</h3>${p.parents.map(x=>{const actual=state.people[x.id];return personRow(x.name,`${actual?(actual.alive?actual.age+' ans':'Décédé·e')+' · ':''}Lien ${Math.round(x.bond)}/100`)}).join('')}<p class="hint">Les parents de la naissance initiale sont des figures narratives. Les générations que vous créez et incarnez sont simulées individuellement.</p></div>`}
function confirmSeparate(){modal(`<h2>Terminer cette relation ?</h2><p>Le couple se sépare. Les enfants et vos liens familiaux restent. Une réorganisation simplifiée du foyer retire 30 % de vos liquidités personnelles.</p><button class="btn danger" onclick="document.getElementById('modal').close();act('breakup')">Confirmer la séparation · 1</button>`)}
function familyView(){const p=state.person,all=Object.values(state.people);return`${heading('Une famille. Plusieurs vies possibles.','Chaque personne de votre lignée garde son histoire et son patrimoine.',`<span class="pill">${all.length} personnes · génération ${state.generation}</span>`)}${!p.alive?ending():''}<div class="card"><div class="eyebrow">Vos générations précédentes</div>${state.ancestors.map(a=>{const x=state.people[a.id];return personRow(x.name+' '+x.surname,`${x.age} ans · ${x.alive?'vie autonome':'vie terminée'} · ${x.children.length} enfant(s)`)}).join('')||'<p style="margin-top:15px">Vous êtes la première vie de cette lignée.</p>'}<div class="current-person">${personRow(p.name+' '+p.surname,`${p.age} ans · votre vie actuelle`)}</div><div class="eyebrow" style="margin-top:22px">Vos enfants : les prochains relais</div>${p.children.map(d=>{const x=state.people[d.id];return`<div class="family-branch">${personRow(x.name+' '+x.surname,`${x.age} ans · ${x.job}${x.partner?' · en couple':''} · ${x.children.length} enfant(s)`,x.alive?`<button class="btn" onclick="handoff(${x.id})">Incarner →</button>`:'<span class="tag">Décédé·e</span>')}${x.children.map(d=>{const y=state.people[d.id];return personRow('↳ '+y.name,`${y.age} ans · petit-enfant · ${y.alive?'une vie en cours':'vie terminée'}`)}).join('')}</div>`}).join('')||'<p style="margin-top:15px">Votre histoire n’a pas de descendant pour le moment. Vous pouvez aussi conserver ce récit pour lui-même.</p>'}</div><div class="grid"><div class="card"><h3>Continuer sans effacer le passé</h3><p>Vous incarnez votre enfant à son âge actuel. Son partenaire, ses enfants, son métier, ses compétences et son épargne sont conservés. Les autres membres de la famille poursuivent leur vie.</p><p>Votre personnage précédent continue de vieillir, de travailler et d’entretenir sa famille. Son décès déclenche la succession, même après le relais.</p></div><div class="card"><h3>Ce qui se transmet</h3>${micro('Impact cumulé de la lignée',state.legacy.impact)}${micro('Projets accomplis dans cette vie',p.finished.filter(x=>x.success).length)}${micro('Souvenirs de votre personnage',p.memories.length)}<p>À un décès, les actifs sont liquidés et les dettes déduites. Le patrimoine net positif est partagé : moitié au partenaire vivant, puis le reste entre les enfants vivants. Les dettes ne sont pas transmises aux enfants.</p><button class="btn" onclick="exportSave()">Conserver cette branche</button></div></div><div class="card" style="margin-top:22px"><h3>Ce qui vous a marqué</h3>${p.memories.slice().reverse().map(x=>`<div class="data-row"><span>${x.year}</span><b>${esc(x.text)}</b></div>`).join('')||'<p>Les événements de votre vie laisseront leurs traces ici.</p>'}</div>`}
function handoff(id){const x=state.people[id];modal(`<h2>Continuer avec ${esc(x.name)} ?</h2><p>Vous poursuivrez en ${state.year}, à ${x.age} ans, avec sa vie déjà construite. ${x.partner?'Son couple avec '+esc(x.partner.name)+' reste en place. ':''}${x.children.length?'Ses '+x.children.length+' enfant(s) continuent aussi leur histoire.':''}</p>${micro('Métier',esc(x.job))}${micro('Patrimoine net',money(Life.balance(x)))}<p>Le personnage précédent continue de vivre de façon autonome. Exportez la partie si vous souhaitez garder la possibilité de rejouer cette branche autrement.</p><div class="row"><button class="btn" onclick="exportSave()">Exporter d’abord</button><button class="btn primary" onclick="confirmHandoff(${id})">Passer le relais →</button></div>`)}
function ending(){const p=state.person,x=Life.summary(state);return`<div class="result"><div class="eyebrow">${state.year-p.age} — ${state.year}</div><h2 style="margin-top:13px">${esc(p.name)}. Une vie qui ne tient pas dans un score.</h2><p>${p.moves?'Vous avez changé de pays '+p.moves+' fois. ':'Votre histoire s’est inscrite dans un lieu et une époque. '}${x.projects} projet${x.projects>1?'s':''} accompli${x.projects>1?'s':''}, ${x.failed} tentative${x.failed>1?'s':''} à l’issue différente. ${p.children.length?`Votre famille compte ${p.children.length} enfant(s), avec leurs propres rêves.`:'Les personnes rencontrées et les choses créées comptent aussi dans ce que vous laissez.'}</p>${micro('Patrimoine net avant succession',money(x.worth))}${micro('Contribution personnelle',x.impact)}${micro('Par enfant vivant',money(p.estate?.each||0))}<div class="row"><button class="btn primary" onclick="nav('family')">Poursuivre ma lignée →</button><button class="btn" onclick="nav('journal')">Relire ma vie</button><button class="btn" onclick="newGame()">Une autre naissance</button></div></div>`}
function migration(){launchProject('migration')}
function welcome(){baseWelcome();const app=$('#app');app.innerHTML=app.innerHTML.replace('Une simulation de vie & de générations','Lignées 2.0 · Le temps, le risque, la transmission').replace('Une vie complète, à votre rythme.','8 secteurs professionnels, 12 parcours de projets et des générations autonomes.');}
function guide(){modal(`<h2>Votre vie, en cinq gestes.</h2><ol class="guide-list"><li><b>Répondez au chapitre.</b> Les décisions tiennent compte de votre situation et des moyens disponibles.</li><li><b>Choisissez vos initiatives.</b> Apprenez une compétence, préparez une candidature ou entretenez un lien.</li><li><b>Engagez des projets.</b> Ils réservent du temps chaque année. Gardez un revenu et une réserve pour leurs frais.</li><li><b>Laissez le temps avancer.</b> La frise déroule les mois à ×1, ×2 ou ×4. Les petits instants racontent la vie ; les grandes décisions mettent le jeu en pause.</li><li><b>Transmettez.</b> Vous pouvez incarner un enfant avec sa vie déjà construite. Les autres continuent d’exister.</li></ol><div class="notice">Les taux de recrutement, les rendements et les issues des projets sont des estimations du modèle de jeu. Les profils mondiaux de départ restent approximatifs.</div><button class="btn primary" onclick="document.getElementById('modal').close()">À moi d’écrire la suite →</button>`)}
function sources(){baseSources();const d=$('#modal');d.innerHTML=d.innerHTML.replace('Lignées est une simulation jouable en bêta.','Lignées 2.0 est un jeu de simulation textuel.').replace('Les chiffres historiques et futurs restent des scénarios utilisant ces mêmes profils.','Les chiffres historiques et futurs restent des scénarios utilisant ces mêmes profils. Les cycles économiques, les carrières et les projets sont simulés par des règles déterministes, pas par une IA improvisant les résultats.');d.innerHTML+='<p>La deuxième version ajoute cinq compétences, huit secteurs avec quatre niveaux, douze projets, une comptabilité de foyer, des entreprises avec trésorerie et des descendants autonomes. Les hypothèses de gameplay restent distinctes des observations statistiques.</p>';}
if(state){Life.ensure(state);save()}render();
